public void init()
{
    super();

    element.clearResultFields();
    LogMessageOutput.text('');
    element.setStatus(TEST_RunTestDataPreparationStatus::New);
}

private void setStatus(TEST_RunTestDataPreparationStatus _status)
{
    switch (_status)
    {
        case TEST_RunTestDataPreparationStatus::New:
            StatusOutput.text("@SJP:TEST_RunTestDataPreparationStatus_New");
            break;
        case TEST_RunTestDataPreparationStatus::Error:
            StatusOutput.text("@SJP:TEST_RunTestDataPreparationStatus_Error");
            break;
        case TEST_RunTestDataPreparationStatus::Succeeded:
            StatusOutput.text("@SJP:TEST_RunTestDataPreparationStatus_Succeeded");
            break;
    }
}

private void clearResultFields()
{
    JournalIdOutput.text('');
    SalesIdOutput.text('');
    InvoiceIdOutput.text('');
}

private void appendLog(str _message)
{
    str logText = LogMessageOutput.text();

    if (!_message)
    {
        return;
    }

    if (logText)
    {
        logText += '; ';
    }

    logText += _message;
    LogMessageOutput.text(logText);
}

private void appendInfologToLogMessage()
{
    SysInfologEnumerator    enumerator = SysInfologEnumerator::newData(infolog.cut());
    SysInfologMessageStruct messageStruct;

    while (enumerator.moveNext())
    {
        messageStruct = new SysInfologMessageStruct(enumerator.currentMessage());

        if (messageStruct)
        {
            element.appendLog(messageStruct.message());
        }
    }
}

private void runSmokeJob()
{
    ItemId           itemIdValue          = ItemIdInput.text();
    InventLocationId inventLocationIdValue = InventLocationIdInput.text();
    JournalId        journalIdValue;
    SalesId          salesIdValue;
    CustInvoiceJour  custInvoiceJour;

    element.setStatus(TEST_RunTestDataPreparationStatus::New);
    element.clearResultFields();
    LogMessageOutput.text('');

    infolog.clear();

    try
    {
        if (!InventTable::find(itemIdValue).RecId)
        {
            itemIdValue = TEST_CreateReleasedProductJob::createReleasedProduct(itemIdValue);
            info(strFmt("@SJP:TEST_RunTestDataPreparation_ItemCreatedFmt", itemIdValue));
        }

        journalIdValue = TEST_CreateAndPostMovementJournalJob::createAndPostForItem(itemIdValue, 1, 1000, inventLocationIdValue);

        if (InventJournalTable::find(journalIdValue).Posted != NoYes::Yes)
        {
            throw error(strFmt("@SJP:TEST_RunTestDataPreparation_JournalNotPostedFmt", journalIdValue));
        }

        info(journalIdValue);

        salesIdValue = TEST_CreateAndPostSalesOrderInvoiceJob::createAndPostSalesInvoice(itemIdValue, 1, inventLocationIdValue);

        select firstonly custInvoiceJour
            order by RecId desc
            where custInvoiceJour.SalesId == salesIdValue;

        if (!custInvoiceJour.RecId)
        {
            throw error(strFmt("@SJP:TEST_RunTestDataPreparation_SalesNotFoundFmt", salesIdValue));
        }

        info(strFmt("@SJP:TEST_RunTestDataPreparation_InvoiceCreatedFmt", custInvoiceJour.InvoiceId, salesIdValue));

        ItemIdInput.text(itemIdValue);
        JournalIdOutput.text(journalIdValue);
        SalesIdOutput.text(salesIdValue);
        InvoiceIdOutput.text(custInvoiceJour.InvoiceId);

        element.setStatus(TEST_RunTestDataPreparationStatus::Succeeded);
    }
    catch (Exception::CLRError)
    {
        error("@SJP:TEST_RunTestDataPreparation_ClrError");
        element.setStatus(TEST_RunTestDataPreparationStatus::Error);
    }
    catch (Exception::Error)
    {
        element.setStatus(TEST_RunTestDataPreparationStatus::Error);
    }

    element.appendInfologToLogMessage();
}

